<script setup lang="ts">
import {Head} from '@inertiajs/vue3';import {computed,onMounted,ref} from 'vue';import api from '@/utils/api';
const rows=ref<any[]>([]),month=ref(new Date()),selected=ref(new Date().toISOString().slice(0,10)),busy=ref(false);const form=ref({contact_name:'',phone:'',social_media:'',reserved_at:'',party_size:1,status:'confirmed',notes:''});const key=(d:Date)=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');const days=computed(()=>{const y=month.value.getFullYear(),m=month.value.getMonth(),f=new Date(y,m,1),o:any[]=[];for(let i=0;i<f.getDay();i++)o.push(null);for(let d=1;d<=new Date(y,m+1,0).getDate();d++){const z=new Date(y,m,d),k=key(z);o.push({d,k,count:rows.value.filter(x=>String(x.reserved_at).slice(0,10)===k&&!['cancelled','no_show'].includes(x.status)).length})}return o});const selectedRows=computed(()=>rows.value.filter(x=>String(x.reserved_at).slice(0,10)===selected.value));async function load(){busy.value=true;try{const y=month.value.getFullYear(),m=month.value.getMonth();rows.value=(await api.get('/api/v1/reservations',{params:{from:key(new Date(y,m,1))+' 00:00:00',to:key(new Date(y,m+1,0))+' 23:59:59'}})).data}finally{busy.value=false}}function move(n:number){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1);load()}async function save(){if(!form.value.contact_name||!form.value.reserved_at)return;await api.post('/api/v1/reservations',form.value);form.value={contact_name:'',phone:'',social_media:'',reserved_at:'',party_size:1,status:'confirmed',notes:''};await load()}async function status(x:any,s:string){await api.patch('/api/v1/reservations/'+x.id,{status:s});await load()}async function del(x:any){if(confirm('Delete this reservation?')){await api.delete('/api/v1/reservations/'+x.id);await load()}}onMounted(load);
</script><template><Head title="Reservations"/><div class="p"><header><div><small>ADMIN / RESERVATIONS</small><h1>Reservation calendar.</h1><p>Plot customer bookings and see upcoming reservations at a glance.</p></div><button @click="load">{{busy?'Refreshing…':'Refresh'}}</button></header><div class="grid"><section class="card"><div class="month"><button @click="move(-1)">←</button><h2>{{month.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}}</h2><button @click="move(1)">→</button></div><div class="week"><b v-for="d in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']">{{d}}</b></div><div class="calendar"><div v-for="(d,i) in days" :key="i" :class="['day',d&&selected===d.k?'on':'']" @click="d&&(selected=d.k)"><template v-if="d"><strong>{{d.d}}</strong><span v-if="d.count">{{d.count}} reservation{{d.count>1?'s':''}}</span></template></div></div></section><section class="card form"><h2>New reservation</h2><input v-model="form.contact_name" placeholder="Contact name *"><input v-model="form.phone" placeholder="Phone number"><input v-model="form.social_media" placeholder="Social media / profile"><input v-model="form.reserved_at" type="datetime-local"><input v-model.number="form.party_size" type="number" min="1"><textarea v-model="form.notes" placeholder="Notes / special requests"></textarea><button class="primary" @click="save">SAVE RESERVATION</button></section></div><section class="card list"><h2>{{new Date(selected+'T00:00:00').toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric'})}}</h2><div v-for="x in selectedRows" :key="x.id" class="row"><div><strong>{{new Date(x.reserved_at).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'})}} · {{x.contact_name}}</strong><p>{{x.party_size}} guest(s) · {{x.phone||'No phone'}} · {{x.social_media||'No social media'}}</p><small>{{x.status}}<template v-if="x.notes"> · {{x.notes}}</template></small></div><div><select :value="x.status" @change="status(x,($event.target as HTMLSelectElement).value)"><option v-for="s in ['pending','confirmed','arrived','completed','cancelled','no_show']" :value="s">{{s}}</option></select><button @click="del(x)">Delete</button></div></div><p v-if="!selectedRows.length">No reservations for this date.</p></section></div></template><style scoped>.p{padding:28px;max-width:1400px;margin:auto;color:#24231e}header,.month,.row{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{font-size:38px;margin:6px 0}small{color:#ad3b19;font-weight:800;text-transform:uppercase}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:22px}.card{background:#fffcf6;border:1px solid #ded7cb;border-radius:8px;padding:20px}.week,.calendar{display:grid;grid-template-columns:repeat(7,1fr)}.week b{text-align:center;padding:12px;font-size:11px}.day{min-height:105px;border:1px solid #ece5da;padding:10px;cursor:pointer}.day.on{outline:2px solid #ad3b19}.day span{display:block;margin-top:12px;font-size:10px;color:#ad3b19;font-weight:800}.form{display:flex;flex-direction:column;gap:10px}input,textarea,select{border:1px solid #d4cdbf;border-radius:5px;padding:12px;background:white}.primary{background:#24231e;color:white;padding:14px;font-weight:800}.list{margin-top:18px}.row{padding:15px 0;border-top:1px solid #ece5da}.row p{margin:5px 0;color:#68665f}.row button{margin-left:8px}@media(max-width:850px){.grid{grid-template-columns:1fr}.day{min-height:70px}.p{padding:16px}}</style>